package kr.memorynotes;
import android.app.*;import android.content.*;import android.os.Bundle;import android.graphics.*;import org.json.*;import java.io.*;import java.util.*;
public class SmokeRunner extends Instrumentation {
 int assertions=0;
 static String repeat(String s,int count){StringBuilder b=new StringBuilder();for(int i=0;i<count;i++)b.append(s);return b.toString();}
 public void onCreate(Bundle args){super.onCreate(args);start();}
 void check(boolean value,String message){assertions++;if(!value)throw new AssertionError(message);}
 public void onStart(){Bundle result=new Bundle();try{
  Context c=getTargetContext();NoteDb db=new NoteDb(c);JSONObject before=db.snapshot();
  try{
   Note n=new Note();n.subject="hvac";n.title="한글 <>& πdL";n.body="수분 → {{산 생성}}\n"+repeat("긴 한글",2000);n.type="오답노트";n.question="외표면적 공식?";n.answer="πdL";n.mine="πd²/4";n.reason="단면적과 혼동";n.caution="관의 옆면적";
   File imageDir=new File(c.getFilesDir(),"images");imageDir.mkdirs();String imageId=UUID.randomUUID()+".img";Bitmap bitmap=Bitmap.createBitmap(20,20,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.GREEN);try(OutputStream out=new FileOutputStream(new File(imageDir,imageId))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}JSONObject im=new JSONObject();im.put("file",imageId);im.put("masks",new JSONArray("[[0.1,0.2,0.8,0.9]]"));n.images.put(im);db.save(n);check(db.query("πdL").size()>0,"Korean search");Note read=db.query("πdL").get(0);check(read.body.equals(n.body),"long Korean persistence");db.renameGroup("subjects","hvac","공조냉동 테스트");check(db.query("πdL").get(0).subject.equals("hvac"),"rename stable IDs");db.review(n,0);check(db.history().size()>0,"review history");
   ByteArrayOutputStream out=new ByteArrayOutputStream();new BackupManager(c,db).exportTo(out);byte[] backup=out.toByteArray();db.delete(n);new BackupManager(c,db).validateAndRestore(new ByteArrayInputStream(backup));Note restored=db.query("πdL").get(0);check(restored.body.equals(n.body),"backup text roundtrip");String newImage=restored.images.getJSONObject(0).getString("file");check(new File(imageDir,newImage).isFile(),"backup photo restored");check(restored.images.getJSONObject(0).getJSONArray("masks").toString().equals(im.getJSONArray("masks").toString()),"masks restored");check(restored.rating==0,"review restored");String snapshot=db.snapshot().toString();try{new BackupManager(c,db).validateAndRestore(new ByteArrayInputStream(new byte[]{1,2,3}));throw new AssertionError("accepted broken ZIP");}catch(IOException expected){}check(db.snapshot().toString().equals(snapshot),"corrupt backup preserved DB");
  }finally{db.restore(before);db.close();}
  Intent intent=new Intent(c,MainActivity.class);intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);MainActivity activity=(MainActivity)startActivitySync(intent);waitForIdleSync();runOnMainSync(()->{activity.show("과목");activity.show("검색");activity.show("오답");activity.show("설정");activity.show("홈");activity.edit(null);activity.editor.title.setText("초안 보존 테스트");activity.editor.persistDraft();check(!activity.getPreferences(0).getString("draft","").isEmpty(),"draft written");String savedDraft=activity.getPreferences(0).getString("draft","");activity.show("홈");activity.edit(null);check(savedDraft.equals(activity.getPreferences(0).getString("draft","")),"opening another note preserves draft");activity.getPreferences(0).edit().remove("draft").commit();activity.show("홈");});waitForIdleSync();result.putString("stream","PASS "+assertions+" Android integration assertions; all main screens opened");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL "+e.toString()+"\n"+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
